<?php $pageTitle='Students';$active='students';require_once __DIR__.'/../includes/auth.php';require_role('admin');require_once __DIR__.'/../includes/ui.php';$adminId=(int)user()['id'];$editId=(int)($_GET['edit']??$_POST['user_id']??0);$edit=null;if($editId){$st=$pdo->prepare("SELECT * FROM users WHERE id=? AND role='student'");$st->execute([$editId]);$edit=$st->fetch();}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'';if($action==='save'){ $name=trim($_POST['full_name']??'');$email=trim($_POST['email']??'');$en=trim($_POST['enrollment_no']??'');$dept=trim($_POST['department']??'');$sem=(int)($_POST['semester']??0);$phone=trim($_POST['phone']??'');$status=$_POST['status']??'active';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('Valid name and email are required.');if(!in_array($status,['active','inactive','pending'],true))$status='active';if($edit){$pdo->prepare("UPDATE users SET full_name=?,email=?,enrollment_no=?,department=?,semester=?,phone=?,status=? WHERE id=? AND role='student'")->execute([$name,$email,$en?:null,$dept,$sem?:null,$phone,$status,$editId]);flash('success','Student updated.');}else{$password=$_POST['password']??'';if(strlen($password)<8)throw new RuntimeException('New student password must be at least 8 characters.');$pdo->prepare("INSERT INTO users(full_name,email,password_hash,role,status,enrollment_no,department,semester,phone) VALUES(?,?,?,'student',?,?,?,?,?)")->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$status,$en?:null,$dept,$sem?:null,$phone]);flash('success','Student created.');}redirect('students.php');}elseif($action==='delete'){$uid=(int)$_POST['user_id'];if($uid===$adminId)throw new RuntimeException('You cannot delete your own admin session.');$pdo->prepare("DELETE FROM users WHERE id=? AND role='student'")->execute([$uid]);flash('success','Student deleted.');redirect('students.php');}}catch(Throwable $e){$error=$e->getMessage();}}
$st=$pdo->query("SELECT u.*,COUNT(e.id) course_count FROM users u LEFT JOIN enrollments e ON e.student_id=u.id WHERE u.role='student' GROUP BY u.id ORDER BY u.created_at DESC");$rows=$st->fetchAll();include __DIR__.'/../includes/app_start.php';?>
<div class="page-header"><div><div class="section-kicker mb-2">User management</div><h1>Students</h1><p>Create, edit, activate, and remove student accounts.</p></div><a href="#studentForm" class="btn btn-primary">Add Student</a></div><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-4 mb-4" id="studentForm"><h4><?= $edit?'Edit':'Add' ?> Student</h4><form method="post" class="row g-3 mt-1"><?=csrf_input()?><input type="hidden" name="action" value="save"><input type="hidden" name="user_id" value="<?=$editId?>"><div class="col-md-6"><label class="form-label">Full name</label><input name="full_name" class="form-control" value="<?=e($edit['full_name']??'')?>" required></div><div class="col-md-6"><label class="form-label">Email</label><input name="email" type="email" class="form-control" value="<?=e($edit['email']??'')?>" required></div><div class="col-md-4"><label class="form-label">Enrollment No.</label><input name="enrollment_no" class="form-control" value="<?=e($edit['enrollment_no']??'')?>"></div><div class="col-md-4"><label class="form-label">Department</label><input name="department" class="form-control" value="<?=e($edit['department']??'')?>"></div><div class="col-md-2"><label class="form-label">Semester</label><input name="semester" type="number" min="1" max="12" class="form-control" value="<?=e($edit['semester']??'')?>"></div><div class="col-md-2"><label class="form-label">Status</label><select name="status" class="form-select"><?php foreach(['active','inactive','pending'] as $s):?><option <?=$s===($edit['status']??'active')?'selected':''?>><?=$s?></option><?php endforeach;?></select></div><div class="col-md-6"><label class="form-label">Phone</label><input name="phone" class="form-control" value="<?=e($edit['phone']??'')?>"></div><?php if(!$edit):?><div class="col-md-6"><label class="form-label">Initial Password</label><input name="password" type="password" class="form-control" required></div><?php endif;?><div class="col-12"><button class="btn btn-primary"><?= $edit?'Save Changes':'Create Student' ?></button><?php if($edit):?><a href="students.php" class="btn btn-light ms-2">Cancel</a><?php endif;?></div></form></div><div class="card p-0 overflow-hidden"><div class="table-responsive border-0"><table class="table"><thead><tr><th class="ps-4">Student</th><th>Enrollment</th><th>Department</th><th>Courses</th><th>Status</th><th class="pe-4">Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td class="ps-4"><div class="fw-semibold"><?=e($r['full_name'])?></div><div class="small text-muted"><?=e($r['email'])?></div></td><td><?=e($r['enrollment_no']??'—')?></td><td><?=e($r['department']??'—')?></td><td><?=e($r['course_count'])?></td><td><?=badgeSoft(ucfirst($r['status']),$r['status']==='active'?'success':($r['status']==='pending'?'warning':'secondary'))?></td><td class="pe-4"><a class="btn btn-sm btn-light" href="students.php?edit=<?=$r['id']?>#studentForm">Edit</a><form method="post" class="d-inline" data-confirm="Delete this student account and its enrollments?"><?=csrf_input()?><input type="hidden" name="action" value="delete"><input type="hidden" name="user_id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div>
<?php include __DIR__.'/../includes/app_end.php'; ?>
